INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Community Cloud dasselbe wie eine Public Cloud?', 2, '[{"text": "Nein", "correct": true, "because": "Nur für spezifische Gruppen gedacht"}, {"text": "Ja", "correct": false, "because": "Public ist für alle offen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Vorteil bietet mir diese Cloud-Form?', 3, '[{"text": "Kostenteilung", "correct": true, "because": "Ressourcen werden geteilt"}, {"text": "Maximale Geschwindigkeit", "correct": false, "because": "Nicht primär"}, {"text": "Unbegrenzte Nutzer", "correct": false, "because": "Beschränkt auf Community"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale definieren diese Cloud?', 5, '[{"text": "Gemeinsame Ziele", "correct": true, "because": "Nutzer haben gleiche Anforderungen"}, {"text": "Geteilte Infrastruktur", "correct": true, "because": "Ressourcen werden gemeinsam genutzt"}, {"text": "Öffentlicher Zugriff", "correct": false, "because": "Nur für Mitglieder"}, {"text": "Kostenfrei", "correct": false, "because": "Kosten werden geteilt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie ist für Gruppen mit gleichen Bedürfnissen. b) Sie ist günstiger als eine Private Cloud.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Zielgruppenspezifisch und kostenteilend"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung dieser Cloud?', 4, '[{"text": "Sicherheitsanforderungen", "correct": false, "because": "Kern der Community"}, {"text": "Kostenaufteilung", "correct": false, "because": "Wichtig für Budget"}, {"text": "Farbschema der Webseite", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Verwaltung immer extern ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann intern oder extern sein"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branche nutzt so eine Lösung oft?', 3, '[{"text": "Gesundheitswesen", "correct": true, "because": "Gemeinsame Compliance-Bedürfnisse"}, {"text": "Gaming", "correct": false, "because": "Weniger spezifisch"}, {"text": "Einzelhandel", "correct": false, "because": "Breitere Anforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet diese Cloud-Art?', 5, '[{"text": "Sicherheitsstandards", "correct": true, "because": "An Gruppenbedürfnisse angepasst"}, {"text": "Kosteneffizienz", "correct": true, "because": "Geteilte Ressourcen"}, {"text": "Unbegrenzte Skalierung", "correct": false, "because": "Begrenzt durch Community"}, {"text": "Öffentliche Nutzung", "correct": false, "because": "Nur für Mitglieder"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Sie ist für spezielle Gruppen. b) Sie ist unsicherer als eine Public Cloud. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherer als Public"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Betrieb?', 4, '[{"text": "Gemeinsame Richtlinien", "correct": false, "because": "Notwendig für Zusammenarbeit"}, {"text": "Geteilte Ressourcen", "correct": false, "because": "Kern der Struktur"}, {"text": "3D-Rendering-Software", "correct": true, "because": "Kein Standardbedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist sie teurer als eine Private Cloud?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten werden geteilt"}, {"text": "Ja", "correct": false, "because": "Günstiger durch Teilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind bei der Einrichtung entscheidend?', 4, '[{"text": "Governance-Modell", "correct": true, "because": "Regelt Zusammenarbeit"}, {"text": "Compliance", "correct": true, "because": "Sicherheitsanforderungen"}, {"text": "Maximale Bandbreite", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass sie nur onsite betrieben wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Onsite oder offsite möglich"}, {"text": "Ja", "correct": false, "because": "Flexible Hosting-Optionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl?', 3, '[{"text": "Sicherheitskonformität", "correct": true, "because": "Kern der Community"}, {"text": "Schnelle Einrichtung", "correct": false, "because": "Qualität zählt mehr"}, {"text": "Geringe Latenz", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie fördert Zusammenarbeit. b) Sie ist für alle offen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht öffentlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sektoren profitieren davon?', 5, '[{"text": "Regierung", "correct": true, "because": "Geteilte Compliance"}, {"text": "Bildung", "correct": true, "because": "Kollaboration fördern"}, {"text": "Gaming", "correct": false, "because": "Weniger spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung unwichtig?', 3, '[{"text": "Ressourcenaufteilung", "correct": false, "because": "Kern der Funktionalität"}, {"text": "Sicherheitsprotokolle", "correct": false, "because": "Essenziell"}, {"text": "Markenlogo", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt sie eine Private Cloud?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzt, nicht ersetzt"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob sie für Einzelnutzer geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Für Gruppen konzipiert"}, {"text": "Ja", "correct": false, "because": "Community-fokussiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Verwaltung?', 4, '[{"text": "Regelt Zugriff", "correct": true, "because": "Sichert die Community"}, {"text": "Erhöht Bandbreite", "correct": false, "because": "Technisch nicht relevant"}, {"text": "Verkürzt Ladezeiten", "correct": false, "because": "Nicht primär"}]');
